// Assumes "clipping" means the element's overflow is hidden or scroll-clipped; the fix makes it visible.
await page.goto('/ops/radar');
const radarList = page.getByRole('list', { name: /radar/i });
await expect(radarList).toBeVisible();
await expect(radarList).toHaveCSS('overflow-y', 'visible');

await page.goto('/login');
const landingBand = page.getByRole('region', { name: /band/i });
await expect(landingBand).toBeVisible();
await expect(landingBand).toHaveCSS('overflow-y', 'visible');
